import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class ContractTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void linearCircularAndGrowth(){Object f=TaskBinding.queue(0,2),c=TaskBinding.queue(1,2),d=TaskBinding.queue(2,2);for(Object q:new Object[]{f,c,d}){TaskBinding.put(q,'A');TaskBinding.put(q,'B');assertEquals('A',TaskBinding.get(q));}assertEquals("Очередь переполнена\n",capture(()->TaskBinding.put(f,'C')));assertEquals('B',TaskBinding.get(f));assertEquals("",capture(()->{TaskBinding.put(c,'C');assertEquals('B',TaskBinding.get(c));assertEquals('C',TaskBinding.get(c));TaskBinding.put(d,'C');TaskBinding.put(d,'D');assertEquals('B',TaskBinding.get(d));assertEquals('C',TaskBinding.get(d));assertEquals('D',TaskBinding.get(d));}));}@Test void resetFromPartialAndEmpty(){for(int i=0;i<3;i++){Object q=TaskBinding.queue(i,2);assertEquals("",capture(()->{TaskBinding.reset(q);TaskBinding.put(q,'A');TaskBinding.put(q,'B');assertEquals('A',TaskBinding.get(q));TaskBinding.reset(q);TaskBinding.put(q,'X');TaskBinding.put(q,'Y');assertEquals('X',TaskBinding.get(q));assertEquals('Y',TaskBinding.get(q));}));assertEquals("Очередь пуста\n",capture(()->assertEquals('\0',TaskBinding.get(q))));}} @Test void grownDynamicResetKeepsUsableCapacity(){Object q=TaskBinding.queue(2,1);for(char c='A';c<='H';c++)TaskBinding.put(q,c);assertEquals('A',TaskBinding.get(q));TaskBinding.reset(q);assertEquals("",capture(()->{for(char c='a';c<='h';c++)TaskBinding.put(q,c);for(char c='a';c<='h';c++)assertEquals(c,TaskBinding.get(q));}));}}
